def _migrate_variants_to_options():
    """
    Bisherige Varianten → eine Optionsgruppe (Name = variant_label, meist „Farbe“).
    Eigener Variantenpreis → Aufpreis auf den Produktpreis. Bestand/SKU bleiben,
    weil die Variante selbst erhalten bleibt (sie wird zur Kombination).
    Produkte mit genau einer Variante „Standard“ bekommen keine Gruppe.
    """
    conn = op.get_bind()
    products = conn.execute(sa.text(
        'SELECT id, price_cents, variant_label FROM products')).fetchall()
    for pid, base, label in products:
        variants = conn.execute(sa.text(
            'SELECT id, name, price_cents FROM product_variants '
            'WHERE product_id = :p ORDER BY position, id'), {'p': pid}).fetchall()
        if not variants or (len(variants) == 1 and variants[0][1] == 'Standard'):
            continue
        opt_id = conn.execute(sa.text(
            'INSERT INTO product_options (product_id, name, position) VALUES (:p, :n, 0) '
            'RETURNING id'), {'p': pid, 'n': (label or 'Ausführung')[:50]}).scalar()
        for pos, (vid, name, price) in enumerate(variants):
            surcharge = max(0, (price if price is not None else base) - base)
            val_id = conn.execute(sa.text(
                'INSERT INTO product_option_values (option_id, name, surcharge_cents, position) '
                'VALUES (:o, :n, :s, :pos) RETURNING id'),
                {'o': opt_id, 'n': name[:100], 's': surcharge, 'pos': pos}).scalar()
            conn.execute(sa.text(
                'INSERT INTO variant_option_values (variant_id, value_id) VALUES (:v, :x)'),
                {'v': vid, 'x': val_id})
